    @EventHandler( payloadType=CreateTransactionEvent.class )
    public void handle( CreateTransactionEvent event) {
	    LOGGER.info("handling CreateTransactionEvent - " + event );
	    Transaction entity = new Transaction();
            entity.setTransactionId( event.getTransactionId() );
            entity.setAmount( event.getAmount() );
            entity.setFee( event.getFee() );
            entity.setExchangeRate( event.getExchangeRate() );
            entity.setCreatedAt( event.getCreatedAt() );
            entity.setCompletedAt( event.getCompletedAt() );
            entity.setNarrative( event.getNarrative() );
            entity.setTransactionType( event.getTransactionType() );
            entity.setStatus( event.getStatus() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllTransaction( entity );
    }

