    /**
     * Method to retrieve the Transaction via an TransactionPrimaryKey.
     * @param 	id Long
     * @return 	Transaction
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Transaction handle( FindTransactionQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getTransactionId() );
    }
    
    /**
     * Method to retrieve a collection of all Transactions
     *
     * @param	query	FindAllTransactionQuery 
     * @return 	List<Transaction> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Transaction> handle( FindAllTransactionQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindTransaction,
 * but only if the id matches
 *
 * @param		entity	Transaction
 */
	protected void emitFindTransaction( Transaction entity ) {
		LOGGER.info("handling emitFindTransaction" );
		
	    queryUpdateEmitter.emit(FindTransactionQuery.class,
	                            query -> query.getFilter().getTransactionId().equals(entity.getTransactionId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllTransaction
	 * 
	 * @param		entity	Transaction
	 */
	protected void emitFindAllTransaction( Transaction entity ) {
		LOGGER.info("handling emitFindAllTransaction" );
		
	    queryUpdateEmitter.emit(FindAllTransactionQuery.class,
	                            query -> true,
	                            entity);
	}

